        var html='<p class="dialog-context">'+esc(c.name)+'</p><dl class="info-grid"><div class="wide"><dt>Expediente exacto</dt><dd>'+esc(label)+' · '+esc(draft.id)+'</dd></div><div><dt>Captura del expediente</dt><dd>'+esc(labels[draft.status||draft.state]||'Consultar revisión')+'</dd></div><div><dt>Estado operativo</dt><dd>'+esc(operationalLabel(c))+'</dd></div><div><dt>Responsable</dt><dd>'+esc(labelKam(c.assignedKam))+'</dd></div><div><dt>Última actualización</dt><dd>'+esc(formatDate(draft.updatedAt||draft.createdAt))+' CDMX</dd></div></dl>'+(refs?'<h3 class="section-spacer">Operaciones vinculadas</h3><ul class="identity-matches">'+refs+'</ul>':'')+'<p class="inline-note">Vista de consulta de esta ficha y expediente demo. El titular conserva sus verificaciones y confirmaciones; las decisiones operativas continúan en backoffice.</p>'+renderExpedientSummary(draft)+'<div class="form-actions"><button type="button" data-action="cancel-dialog">Cerrar</button></div>';
