      Object.keys((draft.correctionDraft||{}).fieldHistory||{}).forEach(function(key){draft.correctionDraft.fieldHistory[key].forEach(function(item){entries.push({key:key,item:item,correction:true});});});
      Object.keys(draft.correctionDrafts||{}).forEach(function(requestId){var archived=draft.correctionDrafts[requestId];Object.keys(archived.fieldHistory||{}).forEach(function(key){archived.fieldHistory[key].forEach(function(item){entries.push({key:key,item:item,correction:true});});});});
