      showDialog('Preparar campos observados',html,function(form){var patch={};keys.forEach(function(key){patch[key]=value(form,key);});resultOrThrow(state.assisted.editCorrection(draft.id,{fields:patch},dialogRevision()));closeDialog(true);notice('Corrección provisional guardada. El titular debe revisarla y enviarla.');render();});
