    function documentEvidenceId(meta) {return meta&&typeof meta.evidenceId==='string'?meta.evidenceId:meta&&typeof meta.id==='string'&&meta.contactId&&meta.name&&meta.uploadedAt?meta.id:null;}
    function documentCorrectionEvidence(draft) {
      var result=[];
      function collect(value,depth){if(!value||typeof value!=='object'||depth>6)return;if(documentEvidenceId(value)){result.push(value);return;}if(Array.isArray(value))value.forEach(function(v){collect(v,depth+1);});else Object.keys(value).forEach(function(key){collect(value[key],depth+1);});}
      [draft.documentCorrectionReview,draft.documentCorrectionDraft,draft.documentCorrectionDrafts,draft.documentCorrectionSubmissions,draft.documentCorrectionReceipts].forEach(function(v){collect(v,0);});
      return result;
    }
    function documentVersionRow(meta,label,status) {
      if(!meta)return '';
      var id=documentEvidenceId(meta),name=meta.fileName||meta.name||meta.documentType||meta.type||'Archivo ficticio',statusLabels={requested:'Pendiente de reemplazo',pending:'Pendiente',re_review:'En revisión',approved:'Aprobado',rejected:'Rechazado',draft:'Borrador de reemplazo'};
      return '<div class="evidence-row"><div><strong>'+esc(name)+'</strong><p>'+esc(label)+(status?' · '+esc(statusLabels[status]||status):'')+(meta.uploadedAt?' · '+esc(formatDate(meta.uploadedAt)):'')+(meta.actorId||meta.uploadedBy?' · '+esc(labelKam(meta.actorId||meta.uploadedBy)):'')+'</p></div>'+(id?'<button type="button" data-action="view-evidence" data-id="'+esc(id)+'">Ver / descargar</button>':'<span class="help">Archivo no disponible</span>')+'</div>';
    }
    function renderDocumentCorrections(c,draft) {
      if(!draft||!draft.submissionSnapshot)return '';
      var review=draft.documentCorrectionReview,labels={requested:'Reemplazo pendiente',re_review:'Reemplazo en revisión',approved:'Documento aprobado',rejected:'Reemplazo rechazado'};
      var html='<section class="detail-section"><div class="section-line"><h3>Documentos observados</h3><button type="button" data-action="refresh-document-corrections">Actualizar documentos</button></div>';
      if(!review)return html+'<p class="help">Consulta las observaciones del backoffice. Los archivos originales del expediente se conservan; solo se reemplaza el documento observado.</p></section>';
      var sent=!!(draft.documentCorrectionSubmissions&&draft.documentCorrectionSubmissions[review.requestId]),pending=draft.documentCorrectionDraft,editable=review.status==='requested'&&!sent&&!review.financialLocked;
      html+='<span class="badge '+(review.status==='rejected'?'danger':editable?'warning':'')+'">'+esc(labels[review.status]||review.status)+'</span><p class="inline-note">'+esc(review.reason||'Sin comentario adicional')+'</p><dl class="info-grid"><div><dt>Documento exacto observado</dt><dd>'+esc(review.documentType||'Documento')+'</dd></div><div><dt>ID del documento en backoffice</dt><dd>'+esc(review.docId)+'</dd></div></dl>';
      html+=documentVersionRow(review.activeDocument,'Documento vigente en backoffice',review.activeDocument&&review.activeDocument.status);
      if(review.candidate)html+=documentVersionRow(review.candidate,'Reemplazo recibido por backoffice',review.status);
      if(pending&&pending.requestId===review.requestId&&pending.descriptor)html+=documentVersionRow(pending.descriptor,sent?'Reemplazo enviado por el titular':'Preparado para revisión del titular',sent?'re_review':'draft');
      if(editable)html+='<div class="contact-actions"><button class="primary" type="button" data-action="upload-document-correction">Cargar reemplazo observado</button></div>';
      html+='<p class="help">'+(review.financialLocked?'La aceptación financiera bloquea nuevos reemplazos.':sent?'El titular ya envió este reemplazo. Su revisión continúa en backoffice.':review.status==='rejected'?'El reemplazo rechazado queda en el historial. Una nueva carga requiere otra solicitud del backoffice.':'El KAM prepara el archivo ficticio; el titular debe revisarlo y enviarlo. No se modifica el documento original.')+'</p>';
      var history='';(review.history||[]).forEach(function(v){history+=documentVersionRow(v.document||v.descriptor,'Historial de backoffice · '+(v.requestId||''),v.status);if(v.reason)history+='<p class="help">'+esc(v.reason)+'</p>';});
      (review.approvedDocuments||[]).forEach(function(v){history+=documentVersionRow(v.document||v.descriptor||v,'Versión aprobada en backoffice','approved');});
      if(pending)(pending.versions||[]).forEach(function(v,index){history+=documentVersionRow(v.descriptor,'Captura de reemplazo '+(index+1)+' · '+labelKam(v.actorId),'draft');});
      Object.keys(draft.documentCorrectionDrafts||{}).forEach(function(requestId){var old=draft.documentCorrectionDrafts[requestId];(old.versions||[]).forEach(function(v,index){history+=documentVersionRow(v.descriptor,'Captura archivada · '+requestId+' · versión '+(index+1),'draft');});});
      if(history)html+='<details class="details-form capture-history"><summary>Historial de versiones y revisión</summary><div>'+history+'</div></details>';
      return html+'</section>';
    }
    function refreshDocumentCorrections() {
      var c=contact(),draft=c&&findDraft(c.id);if(!draft||!state.assisted||!state.assisted.receiveDocumentCorrection){notice('La revisión documental no está disponible.',true);return;}
      apply(state.assisted.receiveDocumentCorrection(draft.id,revision()),'Revisión documental del mismo expediente actualizada.');
    }
    function uploadDocumentCorrection() {
      var c=contact(),draft=c&&findDraft(c.id),review=draft&&draft.documentCorrectionReview;if(!review||!state.assisted||!state.assisted.editDocumentCorrectionDraft)return;
      if(!state.evidence){notice('El almacenamiento de archivos no está disponible.',true);return;}
      if(review.status!=='requested'||review.financialLocked||draft.documentCorrectionSubmissions&&draft.documentCorrectionSubmissions[review.requestId]){notice('La revisión actual no permite preparar un reemplazo.',true);return;}
      var html='<form><p class="inline-note">'+esc(review.reason||'Reemplaza únicamente el documento observado')+'</p><dl class="info-grid"><div><dt>Tipo de documento</dt><dd>'+esc(review.documentType)+'</dd></div><div><dt>ID exacto observado</dt><dd>'+esc(review.docId)+'</dd></div></dl><label class="upload-field">Archivo ficticio de reemplazo<input name="file" type="file" required accept="application/pdf,image/png,image/jpeg,image/webp"></label><p class="help">Máximo 5 MiB. La versión anterior se conserva. El titular revisa y envía este reemplazo; el KAM no aprueba ni sustituye el archivo vigente.</p>'+endForm('Guardar reemplazo provisional');
      showDialog('Preparar documento observado',html,async function(form){
        var input=form.elements.namedItem('file'),file=input&&input.files&&input.files[0];if(!file)throw new Error('Selecciona un archivo ficticio de reemplazo.');
        var actorId=state.actor.id,expected=dialogRevision(),intent=state.intentEpoch,meta=null;
        try {
          meta=await state.evidence.put(file,{actorId:actorId,contactId:c.id,documentType:review.documentType});
          var persisted=await state.evidence.get(meta.id);
          if(state.intentEpoch!==intent||state.selected!==c.id)throw new Error('La vista cambió durante la carga; no se guardó el reemplazo.');
          if(state.actor.id!==actorId||!getContact(c.id))throw new Error('El acceso al expediente cambió durante la carga.');
          if(!persisted||!persisted.blob||persisted.id!==meta.id||persisted.contactId!==c.id||persisted.actorId!==actorId||persisted.size!==meta.size||persisted.mimeType!==meta.mimeType||persisted.name!==meta.name||persisted.uploadedAt!==meta.uploadedAt||persisted.blob.size!==meta.size||persisted.blob.type!==meta.mimeType)throw new Error('No pudo verificarse el archivo local de este contacto.');
          if(['application/pdf','image/png','image/jpeg','image/webp'].indexOf(persisted.mimeType)<0)throw new Error('El reemplazo debe ser un PDF o una imagen admitida.');
          resultOrThrow(state.assisted.editDocumentCorrectionDraft(draft.id,{descriptor:meta},expected));
        }catch(error){if(meta)try{await state.evidence.remove(meta.id);}catch(rollback){error.message+=' No se pudo limpiar el archivo local huérfano.';}throw error;}
        closeDialog(true);notice('Reemplazo provisional guardado para el documento observado. El titular debe revisarlo y enviarlo.');render();
      });
    }
