        var saved=await state.evidence.get(id);
        if(intent!==state.intentEpoch)return;
        if(state.actor.id!==actorId||state.selected!==targetId||!hasEvidenceAccess(id,targetId))throw new Error('El acceso a la ficha cambió. Vuelve a seleccionar el archivo.');
